-- Voltaic for Neovim. Generated by design/themes.sh - do not edit.
--
--   require("voltaic.theme").setup()        -- follows background
--   require("voltaic.theme").setup("light")
--
-- Links Treesitter capture groups rather than legacy syntax groups, so
-- it colours whatever tree-sitter-voltaic reports.

local M = {}

M.palette = {
  light = {
    ["copper"] = "#A85C32",
    ["zinc"] = "#8A99A3",
    ["ink"] = "#11181D",
    ["ink-2"] = "#3C4A52",
    ["ink-mute"] = "#5F6F79",
    ["ink-faint"] = "#8B9AA3",
    ["ground"] = "#FFFFFF",
    ["ground-2"] = "#F4F7F8",
    ["rule"] = "#C9D3D8",
    ["arc"] = "#0D6E85",
  },
  dark = {
    ["copper"] = "#D98B5A",
    ["zinc"] = "#AEBEC8",
    ["ink"] = "#E7EFF3",
    ["ink-2"] = "#C2D0D8",
    ["ink-mute"] = "#8CA0AB",
    ["ink-faint"] = "#6B7D88",
    ["ground"] = "#141C21",
    ["ground-2"] = "#1B252B",
    ["rule"] = "#27333B",
    ["arc"] = "#3FB9CE",
  },
}

M.groups = {
  { capture = "@keyword", role = "copper", bold = true, italic = false },
  { capture = "@type", role = "arc", bold = false, italic = false },
  { capture = "@function", role = "ink", bold = false, italic = false },
  { capture = "@constant", role = "copper", bold = false, italic = false },
  { capture = "@string", role = "zinc", bold = false, italic = false },
  { capture = "@number", role = "arc", bold = false, italic = false },
  { capture = "@comment", role = "ink-mute", bold = false, italic = true },
  { capture = "@operator", role = "ink-2", bold = false, italic = false },
  { capture = "@variable", role = "ink", bold = false, italic = false },
  { capture = "@punctuation.delimiter", role = "ink-faint", bold = false, italic = false },
}

function M.setup(variant)
  variant = variant or (vim.o.background == "light" and "light" or "dark")
  local p = M.palette[variant]
  vim.o.background = variant
  vim.cmd("highlight clear")
  vim.g.colors_name = "voltaic"

  vim.api.nvim_set_hl(0, "Normal", { fg = p["ink"], bg = p["ground"] })
  vim.api.nvim_set_hl(0, "LineNr", { fg = p["ink-faint"] })
  vim.api.nvim_set_hl(0, "CursorLineNr", { fg = p["copper"], bold = true })
  vim.api.nvim_set_hl(0, "Cursor", { fg = p["ground"], bg = p["copper"] })
  vim.api.nvim_set_hl(0, "Visual", { bg = p["ground-2"] })
  vim.api.nvim_set_hl(0, "VertSplit", { fg = p["rule"] })
  vim.api.nvim_set_hl(0, "Pmenu", { fg = p["ink"], bg = p["ground-2"] })
  vim.api.nvim_set_hl(0, "PmenuSel", { fg = p["ground"], bg = p["copper"] })

  for _, g in ipairs(M.groups) do
    vim.api.nvim_set_hl(0, g.capture, {
      fg = p[g.role],
      bold = g.bold or nil,
      italic = g.italic or nil,
    })
  end
end

return M
